import { useState } from 'react';
import type { Folder, Props } from './Component';

export type FolderBrowser = {
  path: string[];
  currentPath: string;
  children: Folder[];
  enter: (id: string) => void;
  back: () => void;
};

export function useFolderBrowser(folders: Folder[], onNavigate: Props['onNavigate']): FolderBrowser {
  const [path, setPath] = useState<string[]>([]);
  const names: string[] = [];
  let children: Folder[] = folders;

  for (const id of path) {
    const folder: Folder | undefined = children.find((item: Folder): boolean => item.id === id);
    if (!folder) break;
    names.push(folder.name);
    children = folder.children;
  }

  function enter(id: string): void {
    const nextPath: string[] = [...path, id];
    setPath(nextPath);
    onNavigate([...nextPath]);
  }

  function back(): void {
    if (path.length === 0) return;
    const nextPath: string[] = path.slice(0, -1);
    setPath(nextPath);
    onNavigate([...nextPath]);
  }

  return { path, currentPath: '/' + names.join('/'), children, enter, back };
}
